import{_ as n,H as a,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"12｜珠联璧合：Skills 与 SubAgent 配合实战","description":"","frontmatter":{},"headers":[{"level":2,"title":"两个组合方向：谁包含谁","slug":"两个组合方向-谁包含谁","link":"#两个组合方向-谁包含谁","children":[{"level":3,"title":"方向 A：SubAgent 包含 Skill（ skills 字段）","slug":"方向-a-subagent-包含-skill-skills-字段","link":"#方向-a-subagent-包含-skill-skills-字段","children":[]},{"level":3,"title":"方向 B：Skill 包含 SubAgent（ context: fork）","slug":"方向-b-skill-包含-subagent-context-fork","link":"#方向-b-skill-包含-subagent-context-fork","children":[]}]},{"level":2,"title":"构建 Skill：参照着用","slug":"构建-skill-参照着用","link":"#构建-skill-参照着用","children":[]},{"level":2,"title":"三种组合模式：具体咋用","slug":"三种组合模式-具体咋用","link":"#三种组合模式-具体咋用","children":[]},{"level":2,"title":"模式一：SubAgent 预加载 Skills（方向 A 的单次应用）","slug":"模式一-subagent-预加载-skills-方向-a-的单次应用","link":"#模式一-subagent-预加载-skills-方向-a-的单次应用","children":[]},{"level":2,"title":"模式二：Skill + context: fork（方向 B 的直接应用）","slug":"模式二-skill-context-fork-方向-b-的直接应用","link":"#模式二-skill-context-fork-方向-b-的直接应用","children":[]},{"level":2,"title":"模式三：流水线中的 Skill 分工（方向 A 的多阶段串联）","slug":"模式三-流水线中的-skill-分工-方向-a-的多阶段串联","link":"#模式三-流水线中的-skill-分工-方向-a-的多阶段串联","children":[]},{"level":2,"title":"三种模式完整对照","slug":"三种模式完整对照","link":"#三种模式完整对照","children":[]},{"level":2,"title":"本讲小结","slug":"本讲小结","link":"#本讲小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"下一讲预告","slug":"下一讲预告","link":"#下一讲预告","children":[]}],"relativePath":"ClaudeCode工程化实战/12｜珠联璧合：Skills与SubAgent配合实战.md","filePath":"ClaudeCode工程化实战/12｜珠联璧合：Skills与SubAgent配合实战.md","lastUpdated":1779815462000}'),l={name:"ClaudeCode工程化实战/12｜珠联璧合：Skills与SubAgent配合实战.md"};function i(t,s,c,o,r,d){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_12-珠联璧合-skills-与-subagent-配合实战" tabindex="-1">12｜珠联璧合：Skills 与 SubAgent 配合实战 <a class="header-anchor" href="#_12-珠联璧合-skills-与-subagent-配合实战" aria-label="Permalink to &quot;12｜珠联璧合：Skills 与 SubAgent 配合实战&quot;">​</a></h1><blockquote><p>释题：珠联璧合。在这一课中，我们将通过三个项目和一条进化线：从构建生产级 Skill 到确保 SubAgent 真正执行它，把Skills 与 SubAgent 两大关键技术栈融为一体。</p></blockquote><p>你好，我是黄佳。前面我们学习了 Skills 的基础结构（ <a href="https://time.geekbang.org/column/article/945937?utm_source=pinpaizhuanqu&amp;utm_medium=geektime&amp;utm_campaign=guanwang&amp;utm_term=guanwang&amp;utm_content=0511" target="_blank" rel="noreferrer">第 9 讲</a>）、任务型 Skills 实战（ <a href="https://time.geekbang.org/column/article/946297" target="_blank" rel="noreferrer">第 10 讲</a>）和渐进式披露架构（ <a href="https://time.geekbang.org/column/article/946847" target="_blank" rel="noreferrer">第 11 讲</a>）。很明显，Skills 单独使用已经很强，但它真正的威力在于 <strong>与 SubAgent 组合</strong>——把一个通用的 Agent 打造成领域专家。</p><p>在这一讲中，我们先建立起全局视角，再 <strong>设计一个好的 Skill</strong>，再来看 <strong>怎么把Skills和 SubAgents 配合起来用</strong>。</p><p>那么这节课正好可以针对Jxin在子代理第一讲留言中提出的问题，给出答案。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/79e5af0daf62e090yy11246597db9d3e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/79e5af0daf62e090yy11246597db9d3e.png" alt="图片"></a></p><h2 id="两个组合方向-谁包含谁" tabindex="-1">两个组合方向：谁包含谁 <a class="header-anchor" href="#两个组合方向-谁包含谁" aria-label="Permalink to &quot;两个组合方向：谁包含谁&quot;">​</a></h2><p>之前我们讲过了，Skills 解决的是“怎么做”的问题，本质是知识注入——它让同一个 Agent 学会新的能力，就像给一个员工发了一本操作手册，员工还是那个人，只是掌握了更多方法与规范。SubAgents 解决的是“谁来做”的问题，本质是任务委托——它创建一个独立的执行者去完成某件事，就像把任务交给另一位同事，对方拥有自己的上下文、职责边界和决策空间。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/ebf3b49af650a4a8f46e62dfdb4127f0.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/ebf3b49af650a4a8f46e62dfdb4127f0.jpg" alt=""></a></p><p>当你犹豫到底是用 Skill 还是用 SubAgent 的时候，做出选择的核心判断标准在于：这件事到底需要“另一个人”来承担，还是只需要“多一本手册”来指导？</p><p>而更常见的情况是：结合起来使用。当你把两者组合时，本质上只有两个原子方向—— <strong>是 SubAgent 内部加载 Skills，还是由主 Agent 通过 Skills 去编排和调用 SubAgents。</strong></p><h3 id="方向-a-subagent-包含-skill-skills-字段" tabindex="-1">方向 A：SubAgent 包含 Skill（ <code>skills</code> 字段） <a class="header-anchor" href="#方向-a-subagent-包含-skill-skills-字段" aria-label="Permalink to &quot;方向 A：SubAgent 包含 Skill（ \`skills\` 字段）&quot;">​</a></h3><p>此时，你定义子代理的角色，通过 <code>skills</code> 字段给它预加载领域知识。 <strong>SubAgent 是老板，Skill 是工具书。</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .claude/agents/api-doc-generator.md</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>name: api-doc-generator</span></span>
<span class="line"><span>description: Generate API documentation by scanning Express route files.</span></span>
<span class="line"><span>tools: [Read, Grep, Glob, Write, Bash]</span></span>
<span class="line"><span>skills:</span></span>
<span class="line"><span>  - api-generating           # ← 关键：预加载 Skill 作为领域知识</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are an API documentation specialist.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Your Mission</span></span>
<span class="line"><span>Generate or update API documentation for Express.js routes.</span></span></code></pre></div><p>这种情况下，Claude Code的执行流程如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude 主对话: &quot;用 api-doc-generator 为 src/ 生成 API 文档&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>主对话                              SubAgent (api-doc-generator)</span></span>
<span class="line"><span>  │                                    │</span></span>
<span class="line"><span>  ├─ 创建子代理 + 注入 Skill ──────→ │</span></span>
<span class="line"><span>  │                                    ├─ 上下文中已有：角色定义 + SKILL.md 全文</span></span>
<span class="line"><span>  │                                    ├─ 按 SKILL.md 步骤执行任务</span></span>
<span class="line"><span>  │                                    ├─ 使用 Skill 提供的脚本和模板</span></span>
<span class="line"><span>  │                                    ├─ 生成文档</span></span>
<span class="line"><span>  │  ←──── 返回结果摘要 ──────────── │</span></span>
<span class="line"><span>  ├─ 继续对话                          （子代理结束）</span></span></code></pre></div><p>SubAgent 包含 Skill是最常见的情况，适用场景包括子代理需要特定领域的专业知识来完成任务，同一个 Skill 可以被不同角色的 SubAgent 复用，以及需要长期维护的专家型 Agent。</p><h3 id="方向-b-skill-包含-subagent-context-fork" tabindex="-1">方向 B：Skill 包含 SubAgent（ <code>context: fork</code>） <a class="header-anchor" href="#方向-b-skill-包含-subagent-context-fork" aria-label="Permalink to &quot;方向 B：Skill 包含 SubAgent（ \`context: fork\`）&quot;">​</a></h3><p>在这种情况下，Skill 自带任务指令，通过 <code>context: fork</code> 配置自动“派遣”一个子代理去执行。 <strong>Skill 是老板，SubAgent 是执行者。</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: deep-research</span></span>
<span class="line"><span>description: Research a topic thoroughly in the codebase</span></span>
<span class="line"><span>context: fork           # ← 关键：让 Skill 在独立子代理中执行</span></span>
<span class="line"><span>agent: Explore          # ← 子代理类型</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Research $ARGUMENTS thoroughly:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Find relevant files using Glob and Grep</span></span>
<span class="line"><span>2. Read and analyze the code</span></span>
<span class="line"><span>3. Summarize findings with specific file references</span></span></code></pre></div><p>此时的Claude Code执行流程如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户: /deep-research authentication flow</span></span>
<span class="line"><span></span></span>
<span class="line"><span>主对话                              子代理（Explore）</span></span>
<span class="line"><span>  │                                    │</span></span>
<span class="line"><span>  ├─ 创建隔离上下文 ────────────────→ │</span></span>
<span class="line"><span>  │                                    ├─ 收到任务：&quot;Research authentication flow...&quot;</span></span>
<span class="line"><span>  │                                    ├─ Glob/Grep 搜索相关文件</span></span>
<span class="line"><span>  │                                    ├─ Read 分析代码</span></span>
<span class="line"><span>  │                                    ├─ 生成结构化摘要</span></span>
<span class="line"><span>  │  ←──── 返回结果摘要 ──────────── │</span></span>
<span class="line"><span>  ├─ 继续对话（上下文干净）            （子代理结束）</span></span></code></pre></div><p>子代理 <strong>看不到</strong> 你之前的对话历史，因此SKILL.md 的内容成为子代理的任务指令 <strong>。</strong> <code>agent</code> 字段决定子代理类型： <code>Explore</code>（只读探索）、 <code>Plan</code>（规划）、 <code>general-purpose</code>（通用，省略 <code>agent</code> 时默认使用)</p><p><strong>这种应用方式的适用场景是</strong> 研究型任务（深度探索代码库，不污染主对话），重型生成（批量生成文档，中间过程不需要用户看到），以及安全隔离（Skill 的操作不应影响主对话状态）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/85ff4fee38a113b3f2621ff70ddb2451.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/85ff4fee38a113b3f2621ff70ddb2451.jpg" alt=""></a></p><p>下面是两个方向的对照说明表。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/27446fyy953bb69c9f9bc883ba70276e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/27446fyy953bb69c9f9bc883ba70276e.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/7d9623d0e6c61025ac51f63842ab7ee0.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/7d9623d0e6c61025ac51f63842ab7ee0.jpg" alt=""></a></p><h2 id="构建-skill-参照着用" tabindex="-1">构建 Skill：参照着用 <a class="header-anchor" href="#构建-skill-参照着用" aria-label="Permalink to &quot;构建 Skill：参照着用&quot;">​</a></h2><p>下面我们要开始通过示例来讲解二者的组合使用。不过在这之前，先来构建出一个skill，也算是之前内容的又一次复习。</p><p>这个配套项目位于： <code>04-Skills/projects/05-api-generator/</code></p><p>一个生产级的 Skill 的完整架构应该包含这些组件：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.claude/skills/api-generating/          # 标准 Skill 目录</span></span>
<span class="line"><span>├── SKILL.md                            # 入口：路由 + 核心逻辑</span></span>
<span class="line"><span>├── PATTERNS.md                         # 知识：框架识别模式</span></span>
<span class="line"><span>├── STANDARDS.md                        # 规范：文档编写标准</span></span>
<span class="line"><span>├── EXAMPLES.md                         # 示例：输入输出案例</span></span>
<span class="line"><span>├── templates/</span></span>
<span class="line"><span>│   ├── index.md                       # 模板：API 索引页</span></span>
<span class="line"><span>│   ├── endpoint.md                    # 模板：端点文档</span></span>
<span class="line"><span>│   └── openapi.yaml                   # 模板：OpenAPI 规范</span></span>
<span class="line"><span>└── scripts/</span></span>
<span class="line"><span>    ├── detect_routes.py               # 脚本：路由检测</span></span>
<span class="line"><span>    └── validate_openapi.sh            # 脚本：规范验证</span></span></code></pre></div><p>每个组件都有明确的职责。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/92cc14500687eb22fcf5f2763ec8da05.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/92cc14500687eb22fcf5f2763ec8da05.jpg" alt=""></a></p><p>也许你觉得只不过设计个API而已，为什么需要这么多组件？</p><p>但其实一位 API 文档专家，当有人请你写文档时，你需要 <strong>识别技术栈</strong>（Express? FastAPI? Spring?）→ PATTERNS.md、 <strong>遵循规范</strong>（字段命名、格式要求）→ STANDARDS.md、 <strong>参考案例</strong>（不确定时看例子）→ EXAMPLES.md、 <strong>使用模板</strong>（保证一致性）→ templates// <strong>批量处理</strong>（几十个端点不可能手写）→ scripts/。</p><p>这些都是长期的经验积累之后内化的结果，而一个生产级Skill所希望做到的， 就是把这些专家经验形式化。</p><p><strong>主文件 SKILL.md</strong></p><p>主文件不是堆砌所有内容，而是路由器——根据任务需求指向正确的资源。设计要点包括：使用Quick Reference 表格作为一目了然的资源索引，用清晰的步骤告诉 Claude 标准流程，以及按需指引（只在需要时才去读详细文档）。这些都是我们已经熟悉的内容。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: api-documenting</span></span>
<span class="line"><span>description: Generate API documentation from code. Use when the user wants to document APIs, create API reference, generate endpoint documentation, or needs help with OpenAPI/Swagger specs.</span></span>
<span class="line"><span>allowed-tools:</span></span>
<span class="line"><span>  - Read</span></span>
<span class="line"><span>  - Grep</span></span>
<span class="line"><span>  - Glob</span></span>
<span class="line"><span>  - Write</span></span>
<span class="line"><span>  - Bash(python:*)</span></span>
<span class="line"><span>  - Bash(./scripts/*:*)</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span># API Documentation Generator</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Generate comprehensive API documentation from source code.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Quick Reference</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| Task | Resource |</span></span>
<span class="line"><span>|------|----------|</span></span>
<span class="line"><span>| Identify framework | See \`PATTERNS.md\` |</span></span>
<span class="line"><span>| Documentation standards | See \`STANDARDS.md\` |</span></span>
<span class="line"><span>| Example outputs | See \`EXAMPLES.md\` |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Process</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 1: Identify API Endpoints</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Look for route definitions. For framework-specific patterns, see \`PATTERNS.md\`.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 2: Extract Information</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For each endpoint, extract:</span></span>
<span class="line"><span>- HTTP method (GET, POST, PUT, DELETE, etc.)</span></span>
<span class="line"><span>- Path/route</span></span>
<span class="line"><span>- Parameters (path, query, body)</span></span>
<span class="line"><span>- Request/response schemas</span></span>
<span class="line"><span>- Authentication requirements</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 3: Generate Documentation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Use the template in \`templates/endpoint.md\` for each endpoint.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 4: Create Overview</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Generate an index using \`templates/index.md\`.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Output Formats</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Markdown (Default)</span></span>
<span class="line"><span>Generate markdown suitable for README or docs site.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### OpenAPI/Swagger</span></span>
<span class="line"><span>If requested, generate OpenAPI 3.0 spec. See \`templates/openapi.yaml\`.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Automation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To auto-detect routes:</span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span>python scripts/detect_routes.py &amp;lt;source_directory&gt;</span></span></code></pre></div><p>To validate OpenAPI spec:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/validate_openapi.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">spec_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>剩下的各个文件，这里就不再赘述，大家直接去Repo阅读具体的文件和Readme说明就好啦。</p><p>可以在Claude Code中先对这个Skill的能力做一个测试。他会生成10个API端点的完整文档。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/17c79a70731699cbce4d391437b0279b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/17c79a70731699cbce4d391437b0279b.png" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/9822fa90548360ec04378b2126673977.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/9822fa90548360ec04378b2126673977.png" alt="图片"></a></p><h2 id="三种组合模式-具体咋用" tabindex="-1">三种组合模式：具体咋用 <a class="header-anchor" href="#三种组合模式-具体咋用" aria-label="Permalink to &quot;三种组合模式：具体咋用&quot;">​</a></h2><p>第一部分介绍的两个组合方向是基础构件。实战中，它们还衍生出三种组合模式。</p><h2 id="模式一-subagent-预加载-skills-方向-a-的单次应用" tabindex="-1">模式一：SubAgent 预加载 Skills（方向 A 的单次应用） <a class="header-anchor" href="#模式一-subagent-预加载-skills-方向-a-的单次应用" aria-label="Permalink to &quot;模式一：SubAgent 预加载 Skills（方向 A 的单次应用）&quot;">​</a></h2><p>一个子代理预加载一个或多个 Skill，用领域知识增强自己的能力。这是最常见的模式，也是本讲的实战重点。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 子代理在创建时预加载 Skill 作为领域知识</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>name: api-doc-generator</span></span>
<span class="line"><span>skills:</span></span>
<span class="line"><span>  - api-generating              # 预加载 API 文档生成知识</span></span>
<span class="line"><span>---</span></span></code></pre></div><p>配置了Skill的子代理好比一个经过培训的专业技师。</p><p><strong>而同一个 Agent，注入不同的 Skill，就变成不同的专家。这就是组合的力量。</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/d20b530b1b00e8569b53722ef4e93410.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/d20b530b1b00e8569b53722ef4e93410.jpg" alt=""></a></p><p>现在我们来完成最后一步——把 Skill 装进 SubAgent，组装一个领域专家。</p><p>下面就是从单独用Skill到组合使用的进化路线：参考我的代码库 <code>06-agent-skill-combo</code>。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>05-api-generator                        06-agent-skill-combo</span></span>
<span class="line"><span>─────────────                           ─────────────────</span></span>
<span class="line"><span>Skill 独立运行                           Skill + SubAgent 组合</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SKILL.md（6 组件全展示）                  SKILL.md（精简为 3 组件）</span></span>
<span class="line"><span>┌─────────────────────────────┐        ┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│ Quick Reference              │        │ 工作流程 — MANDATORY                 │</span></span>
<span class="line"><span>│ Process: Step 1-4            │   →    │ Step 1: Route Discovery（脚本）       │</span></span>
<span class="line"><span>│ Automation: 可选              │        │ Step 2: Route Analysis（分析）        │</span></span>
<span class="line"><span>│ 6 个引用文件                  │        │ Step 3: Documentation Generation      │</span></span>
<span class="line"><span>└─────────────────────────────┘        └──────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>无 SubAgent 定义                         新增 SubAgent 定义</span></span>
<span class="line"><span>                                       ┌──────────────────────────────────────┐</span></span>
<span class="line"><span>                                       │ api-doc-generator.md                 │</span></span>
<span class="line"><span>                                       │ skills: [api-generating]             │</span></span>
<span class="line"><span>                                       │ &quot;You are an API doc specialist.&quot;     │</span></span>
<span class="line"><span>                                       └──────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>无测试目标                               新增 Express 测试路由</span></span>
<span class="line"><span>                                       ┌──────────────────────────────────────┐</span></span>
<span class="line"><span>                                       │ users.js  — 标准 CRUD（5 条路由）     │</span></span>
<span class="line"><span>                                       │ orders.js — 含链式路由（5 条路由）     │</span></span>
<span class="line"><span>                                       │ 共 10 条路由，验证覆盖率               │</span></span>
<span class="line"><span>                                       └──────────────────────────────────────┘</span></span></code></pre></div><p><strong>首先做的一件事是 Skill 精简化。</strong> 你可能注意到，新的项目中的Skill和刚才创建的独立Skill有点不一样了，从原来的 6 个组件精简为 3 个组件。为什么？因为 SubAgent 已经有了角色定义，Skill 只需提供工作流程和工具：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>05-api-generator（完整展示）         06-agent-skill-combo（实战精简）</span></span>
<span class="line"><span>├── SKILL.md                       ├── SKILL.md          ← 强化工作流程</span></span>
<span class="line"><span>├── PATTERNS.md                    ├── scripts/</span></span>
<span class="line"><span>├── STANDARDS.md                   │   └── detect-routes.py</span></span>
<span class="line"><span>├── EXAMPLES.md                    └── templates/</span></span>
<span class="line"><span>├── templates/ (3 files)               └── api-doc.md</span></span>
<span class="line"><span>└── scripts/ (2 files)</span></span></code></pre></div><p>精简原则是参考型知识（PATTERNS、STANDARDS、EXAMPLES）在主对话场景中有用，但 SubAgent 场景下通常只需要执行流程。这里你可以回顾一下Skill和Sub-Agent的职责划分—— <strong>Skill 负责 HOW，SubAgent 负责 WHO/WHAT</strong>。</p><p><strong>然后是SubAgent 的角色定义。</strong> SubAgent 的 <code>.md</code> 文件只定义角色和使命，具体的工作流程由 Skill 提供。其中 <code>skills: [api-generating]</code> 这一行——就是把&quot;操作手册&quot;交到 SubAgent 手里的那一刻。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .claude/agents/api-doc-generator.md</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>name: api-doc-generator</span></span>
<span class="line"><span>description: Generate comprehensive API documentation by scanning Express route files.</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>tools: [Read, Grep, Glob, Write, Bash]</span></span>
<span class="line"><span>skills:</span></span>
<span class="line"><span>  - api-generating           ← 预加载 Skill</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are an API documentation specialist.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Your Mission</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Generate or update API documentation for Express.js routes.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Workflow</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Run the route detection script as specified in the Skill</span></span>
<span class="line"><span>2. For each discovered route, analyze the handler code</span></span>
<span class="line"><span>3. Generate documentation using the Skill&#39;s template</span></span>
<span class="line"><span>4. Verify all routes are covered (cross-check with script output)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Output</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Write documentation files to \`docs/api/\`</span></span>
<span class="line"><span>- Return a summary to the main conversation:</span></span>
<span class="line"><span>  - Number of routes documented</span></span>
<span class="line"><span>  - Any routes that could not be fully analyzed (with reasons)</span></span>
<span class="line"><span>  - Warnings (missing auth, undocumented parameters, etc.)</span></span></code></pre></div><p>完整项目结构如下所示。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>06-agent-skill-combo/</span></span>
<span class="line"><span>├── .claude/</span></span>
<span class="line"><span>│   ├── agents/</span></span>
<span class="line"><span>│   │   └── api-doc-generator.md     # SubAgent：角色 + 使命（WHO/WHAT）</span></span>
<span class="line"><span>│   ├── skills/</span></span>
<span class="line"><span>│   │   └── api-generating/</span></span>
<span class="line"><span>│   │       ├── SKILL.md              # Skill：工作流程 + 规则（HOW）</span></span>
<span class="line"><span>│   │       ├── scripts/</span></span>
<span class="line"><span>│   │       │   └── detect-routes.py  # 路由检测脚本（处理链式路由）</span></span>
<span class="line"><span>│   │       └── templates/</span></span>
<span class="line"><span>│   │           └── api-doc.md        # 文档模板</span></span>
<span class="line"><span>│   └── settings.local.json           # 权限预配置</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   └── routes/</span></span>
<span class="line"><span>│       ├── users.js                  # 标准 CRUD（5 条路由）</span></span>
<span class="line"><span>│       └── orders.js                 # 含链式路由（5 条路由）</span></span>
<span class="line"><span>├── docs/api/                         # 生成的文档（输出目录）</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><p>下面，在 Claude Code 中，运行 SubAgent：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; 用 api-doc-generator 为 src/ 目录生成 API 文档</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/0583fd15cc4fecfe3c262b6978a0cb12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/0583fd15cc4fecfe3c262b6978a0cb12.png" alt="图片"></a></p><p>检查生成的文档：</p><ul><li><p><code>docs/api/users.md</code> 应包含 5 个端点</p></li><li><p><code>docs/api/orders.md</code> 应包含 5 个端点（含 <code>GET /:id/status</code> 和 <code>PUT /:id/status</code>）</p></li><li><p>需要认证的端点应有 🔒 标记</p></li></ul><p>观察它的工具调用记录，SubAgent 确实执行了脚本、使用了模板，并严格遵循了 SKILL.md 的工作流程。 <strong>Skill 注入真的有效。</strong></p><h2 id="模式二-skill-context-fork-方向-b-的直接应用" tabindex="-1">模式二：Skill + context: fork（方向 B 的直接应用） <a class="header-anchor" href="#模式二-skill-context-fork-方向-b-的直接应用" aria-label="Permalink to &quot;模式二：Skill + context: fork（方向 B 的直接应用）&quot;">​</a></h2><p>Skill 自带任务指令，Skill 包含 SubAgent，通过 <code>context: fork</code> 派一个子代理去执行。这种模式的适用场景是一个独立完整的任务，不需要与主对话交互，执行完把结果送回来就行。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: codebase-research</span></span>
<span class="line"><span>description: Deep research into codebase topics</span></span>
<span class="line"><span>context: fork # 关键点！</span></span>
<span class="line"><span>agent: Explore</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Research $ARGUMENTS thoroughly...</span></span></code></pre></div><p>模式二的配套项目位于： <code>04-Skills/projects/07-skill-fork-demo/</code>。项目结构如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>07-skill-fork-demo/</span></span>
<span class="line"><span>├── .claude/</span></span>
<span class="line"><span>│   └── skills/</span></span>
<span class="line"><span>│       └── code-health-check/</span></span>
<span class="line"><span>│           └── SKILL.md              # context: fork + agent: general-purpose</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── app.js                        # 含硬编码密钥</span></span>
<span class="line"><span>│   ├── routes/</span></span>
<span class="line"><span>│   │   ├── products.js               # 含 SQL 注入、缺少 try/catch</span></span>
<span class="line"><span>│   │   └── categories.js             # 含未使用函数、重复逻辑</span></span>
<span class="line"><span>│   └── utils/</span></span>
<span class="line"><span>│       └── db.js                     # 含 eval() 使用</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><p>在这个项目中，你想做一次代码质量扫描，但不想让大量中间文件内容污染主对话。这正是 <code>context: fork</code> 的典型场景—— <strong>Skill 自己派一个子代理去做，做完把报告送回来</strong>。</p><p>这个项目和上一个项目（模式一）的区别是模式一（Project 05）需要 SubAgent <code>.md</code> 定义文件 + <code>skills:</code> 字段。而模式二（本项目Project 04） <strong>只需要 SKILL.md 一个文件</strong>， <code>context: fork</code> + <code>agent:</code> 自动搞定其它。</p><p>这个Skill 的设计如下。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: code-health-check</span></span>
<span class="line"><span>description: Perform a comprehensive code health check on a directory.</span></span>
<span class="line"><span>context: fork                    # ← 关键：在隔离子代理中执行</span></span>
<span class="line"><span>agent: general-purpose           # ← 子代理类型</span></span>
<span class="line"><span>allowed-tools: [Read, Grep, Glob] # ← 只读，不修改代码</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Code Health Check</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Analyze the codebase at \`$ARGUMENTS\` and produce a structured health report.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Checks to Perform</span></span>
<span class="line"><span>1. File Organization - 文件大小、目录结构</span></span>
<span class="line"><span>2. Error Handling - try/catch、错误传播</span></span>
<span class="line"><span>3. Security Basics - 硬编码密钥、eval()、SQL 注入</span></span>
<span class="line"><span>4. Code Quality - 重复代码、未使用变量</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Output Format</span></span>
<span class="line"><span>Return a structured report:</span></span>
<span class="line"><span>- Overall health score (A/B/C/D/F)</span></span>
<span class="line"><span>- Issues found (categorized by severity: CRITICAL/WARNING/INFO)</span></span>
<span class="line"><span>- Top 3 recommendations</span></span></code></pre></div><p>项目 07 的 <code>src/</code> 中故意埋了多个安全和质量问题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/a9e90a23a800eb43807119fec578cc23.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/a9e90a23a800eb43807119fec578cc23.jpg" alt=""></a></p><p>这些“已知答案“让你可以验证子代理的检查质量。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 进入项目目录后，在 Claude Code 中执行：</span></span>
<span class="line"><span>&gt; /code-health-check src/</span></span></code></pre></div><p>此时Claude Code的执行流程如下：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/code-health-check src/</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ SKILL.md 被激活（context: fork）</span></span>
<span class="line"><span>  ├─ 自动创建 general-purpose 子代理</span></span>
<span class="line"><span>  ├─ 子代理在隔离上下文中：</span></span>
<span class="line"><span>  │   ├─ Glob 扫描 src/ 下所有 .js 文件</span></span>
<span class="line"><span>  │   ├─ Read 每个文件</span></span>
<span class="line"><span>  │   ├─ Grep 搜索 eval(), hardcoded secrets 等模式</span></span>
<span class="line"><span>  │   └─ 生成健康报告</span></span>
<span class="line"><span>  └─ 返回报告到主对话（主对话上下文干净）</span></span></code></pre></div><p>此处的验证要点是：</p><ol><li><p>是否发现了 3 个 CRITICAL 问题？（硬编码密钥、SQL 注入、eval）</p></li><li><p>是否发现了 WARNING 和 INFO 级别问题？</p></li><li><p>主对话上下文是否干净——你看不到子代理读文件的中间过程。</p></li></ol><p>模式二的适用场景总结如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/f4c1762aebd1e57dc0273461d885358f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/f4c1762aebd1e57dc0273461d885358f.jpg" alt=""></a></p><h2 id="模式三-流水线中的-skill-分工-方向-a-的多阶段串联" tabindex="-1">模式三：流水线中的 Skill 分工（方向 A 的多阶段串联） <a class="header-anchor" href="#模式三-流水线中的-skill-分工-方向-a-的多阶段串联" aria-label="Permalink to &quot;模式三：流水线中的 Skill 分工（方向 A 的多阶段串联）&quot;">​</a></h2><p>下面我们再往前走一步。思考一下模式一的自然延伸——多个子代理各自预加载不同的 Skill，按阶段串联执行。每个阶段的输出作为下一阶段的输入。这种模式是和复杂的多阶段任务（我们之前子代理部分也介绍过类似的示例），但此处每个阶段需要通过Skill来配备不同的专业知识。</p><p>&gt; 配套项目： <code>04-Skills/projects/08-skill-pipeline/</code></p><p>项目整体结构如下。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>08-skill-pipeline/</span></span>
<span class="line"><span>├── CLAUDE.md                              ← 流水线编排指令</span></span>
<span class="line"><span>├── .claude/</span></span>
<span class="line"><span>│   ├── agents/</span></span>
<span class="line"><span>│   │   ├── route-scanner.md               ← 阶段 1: 路由扫描专家 (haiku)</span></span>
<span class="line"><span>│   │   ├── doc-writer.md                  ← 阶段 2: 文档编写专家 (sonnet)</span></span>
<span class="line"><span>│   │   └── quality-checker.md             ← 阶段 3: 质量检查专家 (haiku)</span></span>
<span class="line"><span>│   ├── skills/</span></span>
<span class="line"><span>│   │   ├── route-scanning/</span></span>
<span class="line"><span>│   │   │   ├── SKILL.md                   ← 扫描工作流程</span></span>
<span class="line"><span>│   │   │   └── scripts/scan-routes.py     ← 路由扫描脚本</span></span>
<span class="line"><span>│   │   ├── doc-writing/</span></span>
<span class="line"><span>│   │   │   ├── SKILL.md                   ← 文档生成工作流程</span></span>
<span class="line"><span>│   │   │   └── templates/endpoint-doc.md  ← 文档模板</span></span>
<span class="line"><span>│   │   └── quality-checking/</span></span>
<span class="line"><span>│   │       ├── SKILL.md                   ← 质量检查工作流程</span></span>
<span class="line"><span>│   │       └── rules/doc-standards.md     ← 质量标准规则</span></span>
<span class="line"><span>│   └── settings.local.json</span></span>
<span class="line"><span>├── src/routes/</span></span>
<span class="line"><span>│   ├── products.js                        ← 7 条路由（含链式路由）</span></span>
<span class="line"><span>│   └── categories.js                      ← 5 条路由</span></span>
<span class="line"><span>└── docs/                                  ← 生成的文档输出</span></span></code></pre></div><p>一个完整的 API 文档流程可以拆分为三个阶段，每个阶段需要不同的专业能力。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/7763a614505ecbb63fd4b0047c9013f6.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/7763a614505ecbb63fd4b0047c9013f6.jpg" alt=""></a></p><p>每一个阶段的输入输出流程如下。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段 1: 分析子代理</span></span>
<span class="line"><span>  └─ skills: [&quot;code-analyzing&quot;]</span></span>
<span class="line"><span>  └─ 输出：代码分析报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段 2: 重构子代理</span></span>
<span class="line"><span>  └─ skills: [&quot;refactoring-patterns&quot;]</span></span>
<span class="line"><span>  └─ 输入：阶段 1 的报告</span></span>
<span class="line"><span>  └─ 输出：重构方案</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段 3: 测试子代理</span></span>
<span class="line"><span>  └─ skills: [&quot;testing-conventions&quot;]</span></span>
<span class="line"><span>  └─ 输入：阶段 2 的代码变更</span></span>
<span class="line"><span>  └─ 输出：测试结果</span></span></code></pre></div><p><strong>阶段 1：Route Scanner。</strong> 对应 Skill <code>route-scanning/SKILL.md</code>：包含扫描脚本 <code>scan-routes.py</code>，输出 JSON 格式的路由清单。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .claude/agents/route-scanner.md</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>name: route-scanner</span></span>
<span class="line"><span>model: haiku                    # 轻量任务用 haiku</span></span>
<span class="line"><span>tools: [Read, Grep, Glob, Bash]</span></span>
<span class="line"><span>skills:</span></span>
<span class="line"><span>  - route-scanning              # 预加载扫描知识</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>You are a route scanning specialist. You are Stage 1 of a documentation pipeline.</span></span></code></pre></div><p><strong>阶段 2：Doc Writer。</strong> 对应 Skill <code>doc-writing/SKILL.md</code>：包含文档模板 <code>endpoint-doc.md</code>，按模板生成标准化文档。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .claude/agents/doc-writer.md</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>name: doc-writer</span></span>
<span class="line"><span>model: sonnet                   # 需要理解代码逻辑，用 sonnet</span></span>
<span class="line"><span>tools: [Read, Write, Glob]</span></span>
<span class="line"><span>skills:</span></span>
<span class="line"><span>  - doc-writing                 # 预加载文档编写知识</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>You are a documentation writing specialist. You are Stage 2 of a documentation pipeline.</span></span></code></pre></div><p><strong>阶段 3：Quality Checker。</strong> 对应 Skill <code>quality-checking/SKILL.md</code>：包含质量标准规则 <code>doc-standards.md</code>，逐项检查文档质量。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .claude/agents/quality-checker.md</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>name: quality-checker</span></span>
<span class="line"><span>model: haiku                    # 规则检查用 haiku 足够</span></span>
<span class="line"><span>tools: [Read, Grep, Glob]       # 只读，不修改文档</span></span>
<span class="line"><span>skills:</span></span>
<span class="line"><span>  - quality-checking            # 预加载质量检查知识</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>You are a documentation quality specialist. You are Stage 3 of a documentation pipeline.</span></span></code></pre></div><p>流水线的编排逻辑写在 <code>CLAUDE.md</code> 中：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># API Documentation Pipeline</span></span>
<span class="line"><span></span></span>
<span class="line"><span>When the user asks to run the documentation pipeline:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Stage 1: Route Scanning</span></span>
<span class="line"><span>Use the \`route-scanner\` agent to scan the source directory.</span></span>
<span class="line"><span>Collect the route manifest (JSON) from its output.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Stage 2: Documentation Generation</span></span>
<span class="line"><span>Use the \`doc-writer\` agent to generate documentation.</span></span>
<span class="line"><span>Pass the route manifest from Stage 1 as input context.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Stage 3: Quality Validation</span></span>
<span class="line"><span>Use the \`quality-checker\` agent to validate the generated docs.</span></span>
<span class="line"><span>Report the quality verdict to the user.</span></span></code></pre></div><p>编排的关键在于每个阶段的输出是下一阶段的输入。Claude 主对话扮演“项目经理”角色，依次调用三个专家。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/2d08b185331d353711f91314918a29e8.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/2d08b185331d353711f91314918a29e8.jpg" alt=""></a><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/59ef2ef9fd80d3925b9b48feb76939fb.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/59ef2ef9fd80d3925b9b48feb76939fb.jpg" alt=""></a></p><p>下面进行运行与验证。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 先验证扫描脚本</span></span>
<span class="line"><span>python3 .claude/skills/route-scanning/scripts/scan-routes.py src/</span></span>
<span class="line"><span># 预期：发现 12 条路由（products 7 条 + categories 5 条）</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 运行完整流水线</span></span>
<span class="line"><span>&gt; 对 src/ 目录运行文档流水线</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 或者分阶段手动运行</span></span>
<span class="line"><span>&gt; 用 route-scanner 扫描 src/ 目录的路由</span></span>
<span class="line"><span>&gt; 用 doc-writer 根据上面的路由清单生成文档</span></span>
<span class="line"><span>&gt; 用 quality-checker 验证 docs/ 目录下生成的文档</span></span></code></pre></div><p>验证时需要注意下面几件事：</p><ol><li><p>阶段 1 是否发现了全部 12 条路由？（包括链式路由 <code>/:id/reviews</code>）</p></li><li><p>阶段 2 是否生成了 <code>docs/products-api.md</code> 和 <code>docs/categories-api.md</code>？</p></li><li><p>阶段 3 的质量报告是 PASS 还是 NEEDS_REVISION？</p></li></ol><p>对于流水线模式的设计，需要注意下面几个要点。</p><p><strong>要点一：定义清晰的阶段间接口</strong></p><p>每个阶段的 SKILL.md 都明确写了输出格式。</p><ul><li><p>阶段 1 输出 JSON 路由清单</p></li><li><p>阶段 2 输出文件列表 + 路由覆盖数</p></li><li><p>阶段 3 输出 PASS/NEEDS_REVISION 报告</p></li></ul><p>这些就是阶段间的“接口合约”。</p><p><strong>要点二：每个 Skill 只关注一件事</strong></p><ul><li><p><code>route-scanning</code> 只扫描路由，不生成文档。</p></li><li><p><code>doc-writing</code> 只生成文档，不检查质量。</p></li><li><p><code>quality-checking</code> 只检查质量，不修改文档。</p></li></ul><p><strong>单一职责</strong> 让每个 Skill 更简洁、更可测试、更可复用。</p><p><strong>要点三：编排逻辑集中管理</strong></p><p>流水线的顺序、数据传递逻辑都放在 <code>CLAUDE.md</code> 中。如果要调整流程（比如跳过阶段 3），只需修改 <code>CLAUDE.md</code>，不需要动 Skill 或 SubAgent。</p><h2 id="三种模式完整对照" tabindex="-1">三种模式完整对照 <a class="header-anchor" href="#三种模式完整对照" aria-label="Permalink to &quot;三种模式完整对照&quot;">​</a></h2><p>为了帮你更好地理解和区分，我将这三种模式总结成了一张表。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/33070451d0f81ceac595d93dd9ed6af2.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/33070451d0f81ceac595d93dd9ed6af2.jpg" alt=""></a></p><p>实际项目中，你觉得哪种模式最常用？——我感觉当然是第一种。</p><h2 id="本讲小结" tabindex="-1">本讲小结 <a class="header-anchor" href="#本讲小结" aria-label="Permalink to &quot;本讲小结&quot;">​</a></h2><p>好，这一讲就到这里。本讲结构清晰，学习线路明确，比起重复要点，我更想分享一系列选型指南。</p><p>首先是各种场景下的选型矩阵和反模式警告。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/f61eef2abffd4023e9b3f036bfd99d6e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/f61eef2abffd4023e9b3f036bfd99d6e.jpg" alt=""></a><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/538d116e96c06ed720fbd78572e54257.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/538d116e96c06ed720fbd78572e54257.jpg" alt=""></a></p><p><strong>说白了，还是用第一性原理区分什么时候用啥。这基于我们对于他们不同的职能的内化理解。</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/6d92f9c0cff9dbcbbbfdd334eb058441.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/6d92f9c0cff9dbcbbbfdd334eb058441.jpg" alt=""></a></p><p>这种职责划分原则，贯穿几个项目的设计：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    职责划分                                    │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  SubAgent（.md 文件）负责：                                    │</span></span>
<span class="line"><span>│  ────────────────────                                        │</span></span>
<span class="line"><span>│  • WHO: &quot;You are an API documentation specialist&quot;            │</span></span>
<span class="line"><span>│  • WHAT: &quot;Generate API documentation for Express routes&quot;     │</span></span>
<span class="line"><span>│  • WHERE: &quot;Write to docs/api/&quot;                               │</span></span>
<span class="line"><span>│  • OUTPUT: &quot;Return summary with route count and warnings&quot;    │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  Skill（SKILL.md + 附属文件）负责：                             │</span></span>
<span class="line"><span>│  ──────────────────────────                                  │</span></span>
<span class="line"><span>│  • HOW: &quot;Step 1: Run detect-routes.py → Step 2: Analyze&quot;    │</span></span>
<span class="line"><span>│  • WITH WHAT: scripts/detect-routes.py, templates/api-doc.md │</span></span>
<span class="line"><span>│  • BY WHAT STANDARD: &quot;Check auth middleware, mark with 🔒&quot;   │</span></span>
<span class="line"><span>│  • QUALITY: &quot;All routes documented, schemas match code&quot;       │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>这里我也给出组合过程中的排错速查表，供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/292a70f5ee30dacde5341775303dba18.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/947718/292a70f5ee30dacde5341775303dba18.jpg" alt=""></a></p><p>最后的最后，就记住一句话。 <strong>SubAgent 定义“是谁、做什么”，Skill 定义“怎么做、用什么做”。两者各有所长，组合才完整。</strong></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>如果你的 Skill 需要调用外部 API（如翻译服务），你会如何设计？</p></li><li><p>模板和 CLAUDE.md 中的 prompt 有什么区别？什么时候用模板，什么时候用 prompt？</p></li><li><p>同一个 Skill 被不同角色的 SubAgent 预加载，执行效果会有什么不同？试着设想一个具体场景。</p></li><li><p>在项目 08 的流水线中，如果阶段 3 报告 NEEDS_REVISION，你会如何设计“自动修复”流程？需要修改哪些文件？</p></li><li><p>设计一个你自己项目中的流水线：画出阶段划分、每阶段的 SubAgent 角色和 Skill 职责、阶段间的数据接口。</p></li></ol><h2 id="下一讲预告" tabindex="-1">下一讲预告 <a class="header-anchor" href="#下一讲预告" aria-label="Permalink to &quot;下一讲预告&quot;">​</a></h2><p>本讲我们掌握了 Skills 的高级模式和 SubAgent 配合实战。</p><p>下一讲我们将站在更高的视角—— <strong>Skills 在 Claude Code 五层架构中的定位</strong>，从五层架构全景定位到四种设计模式，看清 Skills 在整个技术栈中的角色，最终画出 Skills 在整个技术栈中的全景定位图。</p><p>欢迎你在留言区和我交流讨论。如果这一讲对你有启发，别忘了分享给身边更多朋友。</p>`,144)])])}const h=n(l,[["render",i]]);export{u as __pageData,h as default};
